        fixture.academy = Some(origin.clone());
        let acting = Arc::clone(&academy);
        let operator = Browser::new(move |_, url| {
            if url.is_some_and(|u| u.path() == "/activate") {
                acting.lock().expect("academy").approved += 1;
            }
